using System;using System.Linq;using System.Collections.Generic;using Mono.Cecil;using Mono.Cecil.Cil;
class ExtractJump {
static ModuleDefinition fixture;
static string Sig(TypeReference t){if(t is GenericParameter g)return(g.Type==GenericParameterType.Method?"!!":"!")+g.Position;if(t is GenericInstanceType x)return Sig(x.ElementType)+"<"+string.Join(",",x.GenericArguments.Select(Sig))+">";if(t is ByReferenceType b)return Sig(b.ElementType)+"&";return t.FullName;}
static TypeReference Type(TypeReference t){if(t is GenericInstanceType g){var v=new GenericInstanceType(Type(g.ElementType));foreach(var a in g.GenericArguments)v.GenericArguments.Add(Type(a));return v;}if(t is ByReferenceType b)return new ByReferenceType(Type(b.ElementType));return fixture.GetType(t.FullName)??fixture.ImportReference(t);}
static object Member(object o){if(o is GenericInstanceMethod g){var v=new GenericInstanceMethod((MethodReference)Member(g.ElementMethod));foreach(var a in g.GenericArguments)v.GenericArguments.Add(Type(a));return v;}if(o is TypeReference t)return Type(t);if(o is FieldReference f){var owner=fixture.GetType(f.DeclaringType.FullName);return owner==null?fixture.ImportReference(f):owner.Fields.SingleOrDefault(x=>x.Name==f.Name)??throw new Exception("Missing fixture field: "+f.FullName);}if(o is MethodReference m){var owner=fixture.GetType(m.DeclaringType.FullName);return owner==null?fixture.ImportReference(m):owner.Methods.SingleOrDefault(x=>x.Name==m.Name&&x.Parameters.Count==m.Parameters.Count&&string.Join(",",x.Parameters.Select(p=>Sig(p.ParameterType)))==string.Join(",",m.Parameters.Select(p=>Sig(p.ParameterType))))??throw new Exception("Missing fixture method: "+m.FullName);}return o;}
static void Copy(MethodDefinition from,MethodDefinition to){var body=new MethodBody(to){InitLocals=from.Body.InitLocals};var locals=new Dictionary<VariableDefinition,VariableDefinition>();foreach(var l in from.Body.Variables){var v=new VariableDefinition(Type(l.VariableType));locals[l]=v;body.Variables.Add(v);}var ins=from.Body.Instructions.ToDictionary(i=>i,i=>Instruction.Create(OpCodes.Nop));foreach(var i in from.Body.Instructions){var v=ins[i];v.OpCode=i.OpCode;v.Operand=i.Operand is Instruction branch?ins[branch]:i.Operand is Instruction[] branches?branches.Select(b=>ins[b]).ToArray():i.Operand is VariableDefinition l?locals[l]:i.Operand is ParameterDefinition p?to.Parameters[p.Index]:Member(i.Operand);body.Instructions.Add(v);}foreach(var h in from.Body.ExceptionHandlers){Func<Instruction,Instruction> map=i=>i==null?null:ins[i];body.ExceptionHandlers.Add(new ExceptionHandler(h.HandlerType){TryStart=map(h.TryStart),TryEnd=map(h.TryEnd),HandlerStart=map(h.HandlerStart),HandlerEnd=map(h.HandlerEnd),CatchType=h.CatchType==null?null:Type(h.CatchType),FilterStart=map(h.FilterStart)});}to.Body=body;}
static void CopyIterator(ModuleDefinition game,string ownerName,string factoryName){var owner=game.GetType(ownerName);var from=owner.Methods.Single(m=>m.Name==factoryName);var src=((MethodReference)from.Body.Instructions.Single(i=>i.OpCode==OpCodes.Newobj).Operand).DeclaringType.Resolve();var target=new TypeDefinition(src.Namespace,src.Name,src.Attributes,Type(src.BaseType));fixture.GetType(owner.FullName).NestedTypes.Add(target);foreach(var f in src.Fields)target.Fields.Add(new FieldDefinition(f.Name,f.Attributes,Type(f.FieldType)));foreach(var f in src.Interfaces)target.Interfaces.Add(new InterfaceImplementation(Type(f.InterfaceType)));foreach(var m in src.Methods){var n=new MethodDefinition(m.Name,m.Attributes,Type(m.ReturnType));foreach(var p in m.Parameters)n.Parameters.Add(new ParameterDefinition(p.Name,p.Attributes,Type(p.ParameterType)));target.Methods.Add(n);}foreach(var m in src.Methods){var n=target.Methods.Single(x=>x.Name==m.Name);foreach(var o in m.Overrides)n.Overrides.Add((MethodReference)Member(o));Copy(m,n);}Copy(from,fixture.GetType(owner.FullName).Methods.Single(m=>m.Name==from.Name));
}
static void Main(string[] a){using(var game=ModuleDefinition.ReadModule(a[0]))using(fixture=ModuleDefinition.ReadModule(a[1])){
CopyIterator(game,"CharacterActionMoveStepJump","RollChecksIfNecessary");
CopyIterator(game,"CharacterActionCastSpell","CounterEffectAction");
foreach(var name in new[]{"Run","Reset"})Copy(game.GetType("TA.Coroutine").Methods.Single(m=>m.Name==name),fixture.GetType("TA.Coroutine").Methods.Single(m=>m.Name==name));
var unverified=fixture.GetType("AwaitEh").NestedTypes.Single(t=>t.Name.StartsWith("<BranchUnverified>"));var unverifiedMove=unverified.Methods.Single(m=>m.Name=="MoveNext");var stateStore=unverifiedMove.Body.Instructions.Single(i=>i.OpCode==OpCodes.Stfld&&((FieldReference)i.Operand).Name=="<>1__state"&&i.Previous.OpCode==OpCodes.Ldc_I4_1);var processor=unverifiedMove.Body.GetILProcessor();processor.InsertBefore(stateStore,Instruction.Create(OpCodes.Ldc_I4_0));processor.InsertBefore(stateStore,Instruction.Create(OpCodes.Add));
fixture.Write(a[1]+".patched");}System.IO.File.Delete(a[1]);System.IO.File.Move(a[1]+".patched",a[1]);}
}
